mapper.select:
/* 관리자 (권한관리) 역할권한 조회 쿼리 (searchRoleAuth)*/ select ROLE_ID as roleId ,ROLE_NM as roleNm ,USE_YN as useYn from ocuoc_ROLEM_M where 1=1
and ROLE_ID like '%'||#{roleId}||'%'
and ROLE_NM like '%'||#{roleNm}||'%'

mapper.delete:
/* 관리자 (권한관리) 역할권한 삭제 쿼리 (deleteRole)*/
DELETE
FROM ocuoc_ROLEM_M
WHERE ROLE_ID = #{roleId}

/* 관리자 (권한관리:전체) 버튼권한 삭제 쿼리 (deleteRoleButtion)*/
DELETE
FROM ocuoc_USBTN_m
WHERE ROLE_ID = #{roleId}

/* 관리자 (권한관리:전체) 메뉴권한 삭제 쿼리 (deleteRoleMenu)*/
DELETE
FROM ocuoc_usmua_r
WHERE ROLE_ID = #{roleId}

/* 관리자 (권한관리:전체) 사용자권한 삭제 쿼리 (deleteRoleUser)*/
DELETE
FROM ocuoc_USROL_R
WHERE ROLE_ID = #{roleId}

/* 관리자 (권한관리:단일) 메뉴권한 삭제 쿼리 (deleteMenuParmission)*/
DELETE
FROM ocuoc_usmua_r
WHERE ROLE_ID = #{roleId}

mapper.insert:
/* 관리자 (권한관리) 메뉴권한 저장 쿼리 (insertMenuParmission)*/
INSERT INTO ocuoc_usmua_r
(
	ROLE_ID
, MENU_ID
, USE_YN
, FRST_REG_EMPNO
, FRST_REG_DTTM
)
VALUES
	(
		#{roleId}
	, #{menuId}
	, 'Y'
	, #{frstRegEmpno}
	, TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	)

mapper.delete:
/* 관리자 (권한관리:단일) 사용자권한 삭제 쿼리 (deleteUser)*/
DELETE
FROM ocuoc_USROL_R
WHERE ROLE_ID = #{roleId}
  and USER_ID = #{userId}

/* 관리자 (권한관리:단일) 버튼권한 삭제 쿼리 (deleteUserBtnParmission)*/
DELETE
FROM ocuoc_USBTN_m
WHERE ROLE_ID = #{roleId}
  and MENU_ID = #{menuId}

mapper.insert:
/* 관리자 (권한관리) 버튼권한 저장 쿼리 (insertUserBtnParmission)*/
INSERT INTO ocuoc_USBTN_m
(
	ROLE_ID
, MENU_ID
, BTN_CD
, USE_YN
, FRST_REG_EMPNO
, FRST_REG_DTTM
)
VALUES
	(
		#{roleId}
	, #{menuId}
	, #{btnCd}
	, 'Y'
	, #{frstRegEmpno}
	, TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	)

mapper.select:
/* 사용자정보 모달 조회 쿼리 (searchUserList)*/ select A.EMPNO AS empNo , A.EMP_KOR_FLNM AS empKorFlnm , A.BLNG_BRCD AS blngBrcd , B.BR_NM AS brNm , A.BSORGCD AS bsorgcd , A.EMP_JOBCLS_CD AS empJobclsCd , (SELECT CD_NM FROM OCUOC_CCDTL_L WHERE CD_GROUP = '217000' AND CD_VAL = A.EMP_JOBCLS_CD) AS empJobclsNm , A.HRA_PSTN_CD AS hraPstnCd , A.HRA_PSTN_NM AS hraPstnNm , A.RETM_DT AS retmDt , A.AUT_GRP_CD AS autGrpCd , A.OJBB_EMP_DVCD AS ojbbEmpDvcd , A.WORK_STCD AS workStcd , A.BRDD AS brdd from OCUOC_USERI_M A ,OCUOC_DPRMI_M B where A.BLNG_BRCD = B.BR_CD
and A.EMPNO like '%'||#{empNo}||'%'
and A.EMP_KOR_FLNM like '%'||#{empKorFlnm}||'%'
